import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        long n = nextLong();
        // take: best sum with the last movie chosen; skip: best sum with the last movie skipped.
        long take = 0, skip = Long.MIN_VALUE / 4;
        for (long i = 0; i < n; i++) {
            long rating = nextLong();
            long newTake = Math.max(take, skip) + rating;
            skip = take;
            take = newTake;
        }
        System.out.println(Math.max(take, skip));
    }
}

